sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

     try {
        var cpf = current.variables.renter_cpf ? current.variables.renter_cpf.getDisplayValue().replace(/[^\d]/g, '') : null;
        var cnpj = current.variables.renter_cnpj ? current.variables.renter_cnpj.getDisplayValue().replace(/[^\d]/g, '') : null;
        var customerRole = current.variables.customer_role ? current.variables.customer_role.getValue() : null;

        var aux = new x_asscs_integra.SAPintegraUtils().criarCliente(current, cpf, cnpj, customerRole);

        // Verificar se 'aux' é uma string e faça o parse se necessário
        var auxObj = typeof aux === 'string' ? JSON.parse(aux) : aux;

        // Extraindo os valores de http e responseBody
        var httpStatus = auxObj.http;
        var responseBody = auxObj.responseBody;

        var responseBodyObj = JSON.parse(responseBody);
        var businessPartner = responseBodyObj.BusinessPartner;
        gs.info('Business Partner: ' + businessPartner);


        var msg = '';

        if (httpStatus == 200 || httpStatus == 201 || httpStatus == 202) {
            msg += '\n\n Criação de cliente realizada com sucesso \n\n' + '\n Business Partner: ' + businessPartner;
            current.work_notes = msg;
            current.update();
            // action.setRedirectURL(current);
        } else {
            var codeError = auxObj.code;
            var descriptionError = auxObj.description;
            var message = auxObj.message;
            current.work_notes = '\n\n Houve um erro na criação de cliente.\n\n' + '\n Código: ' + codeError + '\n Descrição: ' + descriptionError + '\n Mensagem: ' + message;
            // current.update();
            // action.setRedirectURL(current);
        }
    } catch (e) {

        // var errorMsg = 'Catch Houve um erro na criação de cliente.\n\n' + (e.message || '');
        var errorMsg = 'Catch Houve um erro na criação de cliente.\n\n';

        if (typeof auxObj !== 'undefined' && auxObj.code && auxObj.description && auxObj.message) {
            errorMsg += '\n Código: ' + auxObj.code + '\n Descrição: ' + auxObj.description + '\n Mensagem: ' + auxObj.message;
        } else {
            errorMsg += e.message || 'Erro desconhecido';
        }

        current.work_notes = errorMsg;
        // current.update();
        // action.setRedirectURL(current);
        gs.addErrorMessage('Houve um erro na criação de cliente. Consulte as notas para mais detalhes.');
    }


})(current, previous);
